package ncasa.expense.infrastructure.outbox;
import tools.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import ncasa.expense.application.port.out.*;import ncasa.expense.domain.*;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;
@Repository public class JpaOutboxAdapter implements TransactionalOutboxPort,OutboxMessageRepository{private final SpringDataOutboxRepository repository;private final ObjectMapper json;public JpaOutboxAdapter(SpringDataOutboxRepository r,ObjectMapper j){repository=r;json=j;}public void append(ExpensePlanId id,List<ExpensePlanEvent> events){for(var event:events){if(repository.existsByDeduplicationKey(event.deduplicationKey()))continue;var e=new JpaOutboxMessageEntity();e.id=UUID.randomUUID();e.aggregateType="ExpensePlan";e.aggregateId=id.value();e.eventType=event.type();e.deduplicationKey=event.deduplicationKey();e.payload=payload(e.id,event);e.occurredAt=event.occurredAt();e.availableAt=event.occurredAt();e.attempts=0;e.status="PENDING";repository.save(e);}}
 @Transactional public List<OutboxMessage> claim(Instant now,int size){var rows=repository.claim(now,now.minus(Duration.ofMinutes(5)),size);rows.forEach(e->{e.status="PROCESSING";e.lockedAt=now;e.attempts++;});repository.flush();return rows.stream().map(e->new OutboxMessage(e.id,e.eventType,e.payload,e.attempts,e.occurredAt)).toList();}
 @Transactional public void published(UUID id,Instant now){repository.findById(id).ifPresent(e->{e.status="PUBLISHED";e.publishedAt=now;e.lockedAt=null;});}
 @Transactional public void retry(UUID id,Instant at,String error,boolean failed){repository.findById(id).ifPresent(e->{e.status=failed?"FAILED":"PENDING";e.availableAt=at;e.lastError=error;e.lockedAt=null;});}
 private String payload(UUID eventId,ExpensePlanEvent event){try{return json.writeValueAsString(Map.of("eventId",eventId.toString(),"eventType",event.type(),"occurredAt",event.occurredAt().toString(),"occurrenceDate",event.occurrenceDate()==null?"":event.occurrenceDate().toString(),"data",event.attributes()));}catch(RuntimeException e){throw new IllegalArgumentException("Cannot serialize outbox event",e);}}
}
